def solve(inputs: dict) -> float:
    X = inputs['X']
    steps = inputs['steps']

    # Keep operations within 32-bit range
    mask_32 = 0xFFFFFFFF

    for _ in range(steps):
        X = X ^ ((X << 11) & mask_32)
        X = X ^ ((X >> 9) & mask_32)
        X = X ^ ((X << 15) & mask_32)
        X = X & mask_32

    return float(X)
